function pigWord(w){
  if(!/^[a-zA-Z]+$/.test(w)) return w;
  var v=function(c){return 'aeiouAEIOU'.indexOf(c)>=0;};
  var i=0; while(i<w.length && !v(w[i])) i++;
  if(i===0) return w+'way';
  var cons=w.slice(0,i), rest=w.slice(i);
  var lower=(w[0]===w[0].toLowerCase());
  var res=rest+cons+'ay';
  if(!lower) res=res.charAt(0).toUpperCase()+res.slice(1).toLowerCase();
  return res;
}
function pigLatin(text){ return text.replace(/[a-zA-Z]+/g, function(mm){return pigWord(mm);}); }
var EXPORTS={pigLatin:pigLatin,pigWord:pigWord};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PigForgePure = EXPORTS; }
